//! SciPy golden parity tests for the filter kernels (issue #7661).
//!
//! `upstream-mocap-preproc/src/filter.rs` claims machine-precision parity with
//! `scipy.signal.butter`/`lfilter`/`lfilter_zi`/`medfilt` and
//! `scipy.ndimage.gaussian_filter1d`. These tests assert that against goldens
//! generated by `tests/generate_parity_filter.py` (SciPy + NumPy), mirroring
//! the `upstream-muscle/tests/parity_hill.csv` pattern.
//!
//! Regenerate goldens with:
//!     python3 tests/generate_parity_filter.py
//!
//! `lfilter`/`lfilter_zi` are private to the crate; their parity is exercised
//! transitively through the public `filtfilt`, whose golden composes the
//! `lfilter` forward/backward passes with the `lfilter_zi` steady-state warm
//! start. `butter_lowpass`, `medfilt_1d`, and `gaussian_filter_1d` are tested
//! directly against their SciPy counterparts.

use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;

use upstream_mocap_preproc::filter::{butter_lowpass, filtfilt, gaussian_filter_1d, medfilt_1d};

// Coefficient/zi parity is exact analytic algebra → tight tolerance.
const TOL_COEFF: f64 = 1e-9;
// Filter outputs accumulate float ops over the signal → slightly looser.
const TOL_SIGNAL: f64 = 1e-6;

struct Row {
    kind: String,
    int_param: usize,
    float_param: f64,
    values: Vec<f64>,
}

fn load_rows() -> Vec<Row> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("parity_filter.csv");
    let text = fs::read_to_string(&path).expect("read parity_filter.csv");
    let mut rows = Vec::new();
    for line in text.lines().skip(1).filter(|l| !l.trim().is_empty()) {
        let mut it = line.split(',');
        let kind = it.next().unwrap().to_string();
        let int_param: usize = it.next().unwrap().trim().parse().unwrap();
        let float_param: f64 = it.next().unwrap().trim().parse().unwrap();
        let values: Vec<f64> = it.map(|s| s.trim().parse::<f64>().unwrap()).collect();
        rows.push(Row {
            kind,
            int_param,
            float_param,
            values,
        });
    }
    assert!(!rows.is_empty(), "parity fixture must not be empty");
    rows
}

/// Index `butter_b`/`butter_a`/`lfilter_zi` rows by `(order, wn)`.
fn key(order: usize, wn: f64) -> String {
    format!("{order}:{wn:.6}")
}

fn max_abs_diff(a: &[f64], b: &[f64]) -> f64 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch ({} vs {})",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b.iter())
        .map(|(x, y)| (x - y).abs())
        .fold(0.0_f64, f64::max)
}

#[test]
fn butter_coefficients_match_scipy() {
    let rows = load_rows();
    let mut b_map: HashMap<String, Vec<f64>> = HashMap::new();
    let mut a_map: HashMap<String, Vec<f64>> = HashMap::new();
    for r in &rows {
        match r.kind.as_str() {
            "butter_b" => {
                b_map.insert(key(r.int_param, r.float_param), r.values.clone());
            }
            "butter_a" => {
                a_map.insert(key(r.int_param, r.float_param), r.values.clone());
            }
            _ => {}
        }
    }
    assert!(!b_map.is_empty(), "expected butter_b goldens");
    for (k, b_gold) in &b_map {
        let a_gold = &a_map[k];
        let mut parts = k.split(':');
        let order: usize = parts.next().unwrap().parse().unwrap();
        let wn: f64 = parts.next().unwrap().parse().unwrap();
        let (b, a) = butter_lowpass(order, wn);
        assert!(
            max_abs_diff(&b, b_gold) <= TOL_COEFF,
            "butter b mismatch for {k}"
        );
        assert!(
            max_abs_diff(&a, a_gold) <= TOL_COEFF,
            "butter a mismatch for {k}"
        );
    }
}

#[test]
fn filtfilt_matches_scipy_including_lfilter_zi_warm_start() {
    let rows = load_rows();
    // Pair filtfilt_input/output by (order, wn).
    let mut inputs: HashMap<String, Vec<f64>> = HashMap::new();
    let mut outputs: HashMap<String, Vec<f64>> = HashMap::new();
    for r in &rows {
        match r.kind.as_str() {
            "filtfilt_input" => {
                inputs.insert(key(r.int_param, r.float_param), r.values.clone());
            }
            "filtfilt_output" => {
                outputs.insert(key(r.int_param, r.float_param), r.values.clone());
            }
            _ => {}
        }
    }
    assert!(!inputs.is_empty(), "expected filtfilt goldens");
    for (k, x) in &inputs {
        let mut parts = k.split(':');
        let order: usize = parts.next().unwrap().parse().unwrap();
        let wn: f64 = parts.next().unwrap().parse().unwrap();
        let (b, a) = butter_lowpass(order, wn);
        let y = filtfilt(&b, &a, x);
        let diff = max_abs_diff(&y, &outputs[k]);
        assert!(diff <= TOL_SIGNAL, "filtfilt mismatch for {k}: diff {diff}");
    }
}

#[test]
fn medfilt_matches_scipy() {
    let rows = load_rows();
    let mut input: Option<Vec<f64>> = None;
    let mut tested = 0;
    for r in &rows {
        if r.kind == "medfilt_input" {
            input = Some(r.values.clone());
        } else if r.kind == "medfilt_output" {
            let x = input.as_ref().expect("medfilt_input precedes output");
            let y = medfilt_1d(x, r.int_param);
            let diff = max_abs_diff(&y, &r.values);
            assert!(diff <= TOL_SIGNAL, "medfilt k={} diff {diff}", r.int_param);
            tested += 1;
        }
    }
    assert!(tested >= 3, "expected several medfilt cases, got {tested}");
}

#[test]
fn gaussian_filter1d_matches_scipy() {
    let rows = load_rows();
    let mut input: Option<Vec<f64>> = None;
    let mut tested = 0;
    for r in &rows {
        if r.kind == "gaussian_input" {
            input = Some(r.values.clone());
        } else if r.kind == "gaussian_output" {
            let x = input.as_ref().expect("gaussian_input precedes output");
            let y = gaussian_filter_1d(x, r.float_param);
            let diff = max_abs_diff(&y, &r.values);
            assert!(
                diff <= TOL_SIGNAL,
                "gaussian sigma={} diff {diff}",
                r.float_param
            );
            tested += 1;
        }
    }
    assert!(tested >= 3, "expected several gaussian cases, got {tested}");
}
